from pathlib import Path
import hashlib,json,re,statistics,sys
p=Path(__file__).resolve().parent
first=json.loads((p/'first-count-attempt/state.json').read_text())
current=json.loads((p/'state.json').read_text())
results={}
events=['cycles','instructions','r08','r0c','r10','r11','r12','r21']
all_keys=[f'stat-{version}-{i}' for i in range(1,6) for version in (0,1)]+['stat-privilege','diagnostic-cpu3-cycles']
for key in all_keys:
    origin=p if key in current else p/'first-count-attempt'
    state=current.get(key,first.get(key))
    entry={'state':'not-started','events':{}}
    if state:
        entry={**state,'state':'discarded' if state.get('contamination') else 'attempted','events':{}}
        out=(origin/f'{key}.stdout').read_text()
        for line in out.splitlines():
            cols=line.split(',')
            if len(cols)<5:continue
            value,unit,event,runtime,percentage=cols[:5]
            if not re.fullmatch(r'(?:cycles|instructions|r(?:08|0c|10|11|12|21))(?::[uk])?',event):continue
            entry['events'][event]={'value':int(value) if value.isdigit() else value,'runtime_ns':runtime,'running_percent':percentage}
    results[key]=entry
summary={}
for version in range(2):
    valid=[results[f'stat-{version}-{i}'] for i in range(1,6) if results[f'stat-{version}-{i}']['state']=='attempted']
    for event in events:
        observations=[e['events'].get(event,{}) for e in valid]
        nums=[o['value'] for o in observations if isinstance(o.get('value'),int)]
        item={'valid_runs':len(valid),'numeric_count':len(nums),'statuses':{value:sum(o.get('value')==value for o in observations) for value in sorted({str(o.get('value')) for o in observations if not isinstance(o.get('value'),int)})}}
        if nums:
            median=statistics.median(nums)
            item.update(min=min(nums),median=median,max=max(nums))
            target=(67108864-1) if event=='r0c' else (2+version*2)*67108864+4 if event=='r08' else None
            if target:item.update(target=target,ratio=median/target,deviation=(median-target)/target)
        summary[f'{version}/{event}']=item
sampling={name:{'record':current.get('record-'+name)} for name in ('idle','load')}
for name,item in sampling.items():
    fn=p/f'sample-{name}-summary.json'
    if fn.is_file():
        item['summary']=json.loads(fn.read_text())
        counts=item['summary']['counts']
        n=sum(counts.values())
        item['summary']['mode_percent']={k:100*v/n for k,v in counts.items()} if n else {}
        nk=counts.get('kernel',0)
        if nk and item['summary']['kernel_symbolized']==nk:
            item['summary']['irq_pct_of_kernel']=100*sum(item['summary']['irq'].values())/nk
            item['summary']['asm_pct_of_kernel']=100*sum(item['summary']['asm_symbol_inference'].values())/nk
out=dict(counts=results,event_summary=summary,sampling=sampling,kallsyms=current.get('kallsyms'),continuation_stop=current.get('stop_reason'))
(p/'results.json').write_text(json.dumps(out,indent=2)+'\n')
for key,value in results.items():
    print(key,value['state'],{k:v['value'] for k,v in value['events'].items()})
for name,result in sampling.items():
    print(name,result.get('record'),{k:v for k,v in result.get('summary',{}).items() if k!='used_symbols'})
print('kallsyms',out['kallsyms'],'stop',out['continuation_stop'])
